import React, { useRef, useState } from 'react';
import './App.css';

export default function App() {
  const [count, setCount] = useState(0);
  const parity = count % 2 === 0 ? 'even' : 'odd';

  const renders = useRef(0);
  renders.current += 1;

  const increment = () => setCount((c) => c + 1);
  const reset = () => setCount(0);

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Debug Double Render</h1>
        <p className="subtitle">Each click should now cause a single render.</p>

        <div className="stats">
          <div className="stat">
            <div className="k">Count</div>
            <div className="v" data-testid="count">{count}</div>
          </div>
          <div className="stat">
            <div className="k">Parity</div>
            <div className="v" data-testid="parity">{parity}</div>
          </div>
          <div className="stat">
            <div className="k">Renders</div>
            <div className="v" data-testid="renders">{renders.current}</div>
          </div>
        </div>

        <div className="actions">
          <button className="btn" onClick={increment}>Increment</button>
          <button className="btn ghost" onClick={reset}>Reset</button>
        </div>

        <div className="panel">
          <div className="label">Expected</div>
          <div className="hint">Render count should increase by 1 per click. Parity stays accurate.</div>
        </div>
      </section>
    </main>
  );
}

