:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  height: 100%;
  background: #0a0a0a;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0a0a0a;
  color: #e5e7eb;
}

.card {
  width: 100%;
  max-width: 640px;
  background: #0b1020;
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 18px;
  display: grid;
  gap: 14px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 12px;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 10px;
}

.stat {
  background: #0a0f1e;
  border: 1px solid #1f2937;
  border-radius: 12px;
  padding: 10px 12px;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.k {
  color: #9ca3af;
  font-size: 12px;
}

.v {
  font-size: 18px;
  font-weight: 900;
}

.actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.btn {
  background: #a3e635;
  color: #111;
  border: none;
  border-radius: 12px;
  padding: 10px 14px;
  font-weight: 800;
  cursor: pointer;
}

.btn.ghost {
  background: transparent;
  color: #e5e7eb;
  border: 1px solid #374151;
}

.panel {
  background: #0a0f1e;
  border: 1px solid #1f2937;
  border-radius: 12px;
  padding: 12px;
  display: grid;
  gap: 6px;
}

.label {
  font-weight: 800;
}

.hint {
  color: #9ca3af;
  font-size: 12px;
  line-height: 1.35;
}

@media (max-width: 560px) {
  .stats {
    grid-template-columns: 1fr;
  }
}
